from __future__ import annotations

import logging
import sys
from pathlib import Path
from typing import Any

from .qwen3_hf_model import clear_hf_model_cache, load_qwen3_hf_bundle

_log = logging.getLogger("transub_engine.asr.qwen3_runtime")

_LANG_MAP = {
    "ja": "Japanese",
    "jp": "Japanese",
    "zh": "Chinese",
    "cn": "Chinese",
    "en": "English",
    # Qwen3-ASR treats Cantonese as its own forced-language name (not Chinese/zh).
    "yue": "Cantonese",
    "cantonese": "Cantonese",
    "zh-yue": "Cantonese",
    "ko": "Korean",
    "auto": None,
}


def clear_model_cache() -> int:
    from .qwen3_batch import _ISLAND_BATCH_CTX, clear_island_batch_oom_caps

    n = clear_hf_model_cache()
    clear_island_batch_oom_caps()
    _ISLAND_BATCH_CTX.clear()
    try:
        import gc

        gc.collect()
    except Exception:
        pass
    try:
        import torch

        if torch.cuda.is_available():
            torch.cuda.empty_cache()
    except Exception:
        pass
    return n


def _probe_torch_cuda_import(timeout_sec: float = 90.0) -> bool:
    """True when a fresh process can import torch with CUDA libs within timeout.

    Windows LoadLibrary on cublas64_*.dll can hang forever (WinError 1114). Probing in a
    child process lets us kill the hang without freezing the serve GIL.
    """
    import os
    import subprocess

    from ..runtime_gpu import _torch_lib_dirs

    code = (
        "import torch\n"
        "print('ok', int(bool(torch.cuda.is_available())), flush=True)\n"
    )
    env = os.environ.copy()
    # Match serve preload: torch\\lib must beat nvidia-* or WinError 1114.
    # ROCm wheels also keep HIP DLLs beside torch/lib or in a sibling package.
    torch_libs = [d for d in _torch_lib_dirs() if d]
    try:
        from ..rocm_device import rocm_runtime_dirs

        torch_libs.extend(d for d in rocm_runtime_dirs() if d and d not in torch_libs)
    except Exception:
        pass
    if torch_libs:
        env["PATH"] = os.pathsep.join(torch_libs + [env.get("PATH", "")])
    try:
        proc = subprocess.Popen(
            [sys.executable, "-c", code],
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            env=env,
        )
    except Exception as err:
        _log.warning("Qwen3-ASR: torch probe spawn failed: %s", err)
        return True  # fall through to in-process import
    try:
        out, err = proc.communicate(timeout=max(15.0, float(timeout_sec)))
    except subprocess.TimeoutExpired:
        try:
            proc.kill()
        except Exception:
            pass
        try:
            proc.wait(timeout=5)
        except Exception:
            pass
        _log.warning(
            "Qwen3-ASR: torch CUDA import probe timed out after %.0fs",
            timeout_sec,
        )
        return False
    if proc.returncode != 0:
        msg = (err or out or "").strip()
        _log.warning("Qwen3-ASR: torch probe failed (code=%s): %s", proc.returncode, msg[:400])
        return False
    return True


def _import_torch(*, prefer_cpu: bool = False):
    """Import torch; recover from Windows cuBLAS WinError 999/1114 after PATH inject.

    Do **not** sticky-set CUDA_VISIBLE_DEVICES="" on conflict: that poisons the whole
    engine process for later batch items (GPU→CPU forever until restart). Prefer
    preload recovery; if still broken, raise so the job can fail/retry after release.
    Explicit prefer_cpu may hide devices for this import only when torch is not yet loaded.
    """
    import os

    from ..device import (
        clear_partial_torch_modules,
        format_torch_cuda_load_failure,
        is_torch_c_extension_loaded,
        is_torch_cublas_load_conflict,
        is_torch_fully_imported,
        is_torch_reimport_poison_error,
        is_torch_reimport_poisoned,
        mark_torch_import_failed_after_native,
        mark_torch_import_ok,
        torch_reimport_poison_message,
    )

    if is_torch_reimport_poisoned():
        raise RuntimeError(torch_reimport_poison_message())

    if is_torch_fully_imported():
        import torch

        mark_torch_import_ok()
        return torch

    prev_cvd = os.environ.get("CUDA_VISIBLE_DEVICES")
    if prefer_cpu:
        # CUDA wheel still loads cublas on import — hide devices only for this attempt
        # and restore so a later process restart / fresh import can see the GPU again.
        os.environ["CUDA_VISIBLE_DEVICES"] = ""

    try:
        import torch

        mark_torch_import_ok()
        return torch
    except OSError as err:
        if not is_torch_cublas_load_conflict(err):
            if is_torch_c_extension_loaded() or is_torch_reimport_poison_error(err):
                mark_torch_import_failed_after_native()
            raise
        if is_torch_c_extension_loaded():
            mark_torch_import_failed_after_native()
            raise RuntimeError(format_torch_cuda_load_failure(err)) from err
        clear_partial_torch_modules()
        # Retry with torch\\lib first (same as serve preload).
        try:
            from ..runtime_gpu import preload_torch_cuda_dlls

            pre = preload_torch_cuda_dlls()
            if pre.get("ok"):
                import torch

                mark_torch_import_ok()
                return torch
        except Exception as pre_err:
            if is_torch_reimport_poison_error(pre_err) or is_torch_c_extension_loaded():
                mark_torch_import_failed_after_native()
            else:
                clear_partial_torch_modules()
        # Do not import under sticky CUDA_VISIBLE_DEVICES="" — that would bind the
        # process to CPU for all subsequent multitask jobs.
        raise RuntimeError(format_torch_cuda_load_failure(err)) from err
    except Exception as err:
        if is_torch_reimport_poison_error(err) or is_torch_c_extension_loaded():
            mark_torch_import_failed_after_native()
            raise RuntimeError(format_torch_cuda_load_failure(err)) from err
        raise
    finally:
        if prefer_cpu:
            if prev_cvd is None:
                os.environ.pop("CUDA_VISIBLE_DEVICES", None)
            else:
                os.environ["CUDA_VISIBLE_DEVICES"] = prev_cvd


def _map_language(language: str | None) -> str | None:
    raw = str(language or "auto").strip().lower()
    if not raw or raw == "auto":
        return None
    if raw in _LANG_MAP:
        return _LANG_MAP[raw]
    # Already a Qwen language name?
    if raw[:1].isupper() or " " in raw:
        return str(language).strip()
    return None


def _device_map(device: str, *, torch_mod: Any | None = None) -> str:
    from ..device import resolve_torch_device_map

    return resolve_torch_device_map(device, torch_mod=torch_mod)



def _enable_cuda_fast_matmul() -> None:
    try:
        from ..rocm_device import torch_is_rocm

        if torch_is_rocm():
            return
    except Exception:
        pass
    try:
        torch = _import_torch()

        if torch.cuda.is_available():
            torch.backends.cuda.matmul.allow_tf32 = True
            torch.backends.cudnn.allow_tf32 = True
    except Exception:
        pass


def _torch_is_rocm() -> bool:
    try:
        from ..rocm_device import torch_is_rocm

        return bool(torch_is_rocm())
    except Exception:
        return False


def _get_asr_model(asr_dir: Path, aligner_dir: Path | None, device: str) -> Any:
    """Resolve device then load Transformers-native bundle."""
    torch = _import_torch()
    resolved = _device_map(device, torch_mod=torch)
    if str(resolved).startswith("cuda"):
        _enable_cuda_fast_matmul()
    return load_qwen3_hf_bundle(
        asr_dir,
        device=resolved,
        aligner_dir=aligner_dir,
        torch_mod=torch,
    )


def _probe_duration_s(media_path: str) -> float:
    try:
        from .whisper_fw import _probe_duration_s as probe

        return float(probe(media_path) or 0)
    except Exception:
        return 0.0


def _empty_cuda_cache() -> None:
    try:
        import gc

        gc.collect()
    except Exception:
        pass
    try:
        import torch

        if torch.cuda.is_available():
            torch.cuda.empty_cache()
    except Exception:
        pass
